    check_even = 0
    check_odd = 0
    for i in range(a, b + 1):
        check = i
        while check != 0:
            du = check % 10
            if du % 2 == 0:
                check_even += 1
            else:
                check_odd += 1
            check //= 10

    return check_even, check_odd


